python
def ribbonRunsBossReceipt(line, k):
    a=line
    out=[]
    i=0
    while i<len(a):
        j=i+1
        while j<len(a) and a[j]==a[i]: j+=1
        out.append(j-i)
        i=j
    return sum((i+1)*x for i,x in enumerate(out))


